export const testFiles = () => readdirSync(TEST_DIR).filter(f => f.endsWith('.test.mjs')).sort().map(f => join(TEST_DIR, f));
export function standInsReady(bin = join(MOCK, 'bin')) {
  const bad = readdirSync(bin).filter(f => !f.startsWith('.')).filter(f => { try { accessSync(join(bin, f), constants.X_OK); return false; } catch { return true; } });
  if (bad.length) throw new Error(`These stand-in commands can’t be run: ${bad.join(', ')}. The test fleet would use this machine’s real ones, so it didn’t start. Run: chmod +x test/mock/bin/*`);
}
export function cleanStale(olderThanMs = 3600000) {
  let removed = 0;
  for (const name of readdirSync(tmpdir()).filter(n => n.startsWith('sct-'))) {
    const d = join(tmpdir(), name);
    try {
      if (Date.now() - statSync(d).mtimeMs < olderThanMs) continue;
      let pids = [];
      try { pids = Object.values(JSON.parse(readFileSync(join(d, 'pids.json'), 'utf8'))); } catch {}
      if (pids.some(p => { try { process.kill(p, 0); return true; } catch (e) { return e.code === 'EPERM'; } })) continue;
      rmSync(d, { recursive: true, force: true }); removed++;
    } catch {}
  }
  return removed;
}
