A3. Replace the `const CONTINUE_DELAY_MS ...` line and the whole of `continueTask` with:
```js
const CONTINUE_DELAY_MS = Number(process.env.SPARK_CONSOLE_CONTINUE_MS || 2000), CONTINUE_MAX = 8, CONTINUE_HOURS = 2, CONTINUE_TRIES = 3;
// Something of this chat is still going: a reply, or an operation started from it.
const chatBusy = id => replying.has(id) || [...jobs.values()].some(j => j.status === 'running' && j.conv === id);
// An operation's result was posted after the last message from the owner's side (theirs, or a carry-on turn's).
const resultSince = conv => conv.messages.slice(conv.messages.map(m => m.role).lastIndexOf('user') + 1).some(m => m.notice && m.operation);
// The one place that decides whether Sparkie carries on with a chat's request now. Called when an operation's result is
// posted (postResult), when a reply ends (sparkieTurn's finish) and every minute (wakeAll, on 20-desired's timer), so it
// no longer matters whether the operation or the reply ended first. Only the minute call (retry) tries a failed
// carry-on turn again. It never throws.
const waking = new Set();
function wakeWork(id, retry = false) {
  try {
    const conv = chatData().conversations.find(c => c.id === id), t = conv?.task;
    if (!t || waking.has(id) || chatBusy(id)) return;
    if (!resultSince(conv) && !(retry && t.failed)) return;
    // The owner's pause holds it (the minute call carries on once it's lifted). Results asked for on Telegram still go.
    if (agentSettings().halted && !agentSettings().autoPaused) { if (t.channel === 'telegram') tellCarry(id, null).catch(() => {}); return; }
    const why = t.failed >= CONTINUE_TRIES ? `it couldn’t answer ${CONTINUE_TRIES} times in a row`
      : t.continuations >= CONTINUE_MAX ? `it had already carried on ${CONTINUE_MAX} times`
        : Date.now() - Date.parse(t.at) > CONTINUE_HOURS * 3600000 ? `more than ${CONTINUE_HOURS} hours have passed since you asked` : null;
    if (why) { giveUp(conv, why); return; }
    waking.add(id);
    setTimeout(() => { waking.delete(id); continueTask(id).catch(e => console.error(`Carrying on in ${id}: ${e.message}`)); }, CONTINUE_DELAY_MS).unref?.();
  } catch (e) { console.error(`Waking ${id}: ${e.message}`); }
}
function wakeAll() { for (const c of chatData().conversations) if (c.task) wakeWork(c.id, true); }
// Carrying on ends for good: the task is dropped and the chat says so once. A request made on Telegram hears it there
// too, after any results still held for it.
function giveUp(conv, why) {
  const t = conv.task, at = new Date().toISOString();
  conv.task = null;
  const content = maskSecrets(`Sparkie stopped carrying on with “${String(t.request).replace(/\s+/g, ' ').slice(0, 200)}”: ${why}. Nothing more will run for it. Say what’s left to pick it up.`);
  conv.messages.push({ role: 'assistant', content, createdAt: at, notice: true });
  conv.updatedAt = at;
  saveChats();
  if (t.channel === 'telegram') tellCarry(conv.id, null).then(() => tell('carry', content)).catch(() => {});
}
async function continueTask(id) {
  const conv = chatData().conversations.find(c => c.id === id), t = conv?.task;
  // (two seconds have passed since wakeWork looked: the owner may have written since)
  if (!t || chatBusy(id)) return;
  const owner = { login: accessList().owner, role: 'owner', nodeIds: null, permissions: ownerPermissions() };
  let message = null;
  try {
    message = await sparkieTurn({ viewer: owner, conv, task: t, channel: t.channel || null, text: /* the existing "[Spark Console] What you started ..." text, unchanged */ });
  } catch (e) { console.error(`Carrying on in ${id}: ${e.message}`); }
  const started = (message?.tools || []).some(u => u.change && u.outcome === 'started');
  // The turn didn't happen, or broke off before starting anything: not counted; the minute call tries it again.
  if (!message || (message.error && !started)) { t.failed = (t.failed || 0) + 1; saveChats(); return; }
  t.failed = 0;
  t.continuations += 1;
  saveChats();
  if (t.channel === 'telegram' && !(conv.task === t && [...jobs.values()].some(j => j.status === 'running' && j.conv === id))) await tellCarry(id, message);
}
```
