```js
/* ───────── a daily copy of the console's state and source on another Spark ───────── */
// People, passkeys, agent keys, chats, recipes that worked and the fleet's record are copied once a day to another
// Spark, and the source kept on Spark 2 (~/spark-console-src) beside them, keeping the last 14 of each, so losing
// Spark 2's disk loses neither. Spark 3 first unless config.json names one, else the next Spark that takes it; never
// Spark 1, the brain's Spark or this one. Each file arrives as <name>.part, is read back whole (gzip -t) and only then
// moved into place, so a copy cut short never replaces a good one.
// backup.json keeps the last try, the last good copy and the day a notice went out, so a restart forgets none of it.
// A copy is due until one has worked today (UTC). It is tried ten minutes after a start, every hour, and as soon as a
// Spark comes back (noteSparkStates). After a whole day without one: one notice a day. It never powers a Spark on.
// To restore: stop the service, then untar a state file into ~/.local/state/spark-console (docs/sharing.md).
const BACKUP_FILE = `${STATE_DIR}/backup.json`;
const BACKUP_ON = !ALL_LOCAL || Boolean(process.env.SPARK_CONSOLE_BACKUP_MS);
// (on the stand-in fleet a source folder is copied only when a test names one)
const SOURCE_DIR = ALL_LOCAL ? process.env.SPARK_CONSOLE_SOURCE_DIR || '' : `${homedir()}/spark-console-src`;
let lastBackup = null, backingUp = false;
try { const kept = readKept(BACKUP_FILE); if (kept && typeof kept === 'object' && !Array.isArray(kept)) lastBackup = kept; } catch {}
const dayOf = t => new Date(t).toISOString().slice(0, 10);
function backupTargets() {
  const first = CONFIG.backupTo || 'spark3';
  return NODES.filter(n => n.host !== 'local' && n.id !== 'spark1' && n.id !== MAIN?.node).sort((a, b) => (b.id === first) - (a.id === first));
}
// One tar stream from this Spark to a file on another. True only when tar, the far side and the read-back all worked.
function sendCopy(target, tarArgs, name) {
  const dir = '"$HOME/.local/share/spark-console/backups"', part = `${dir}/${name}.part`, kind = name.split('-')[0];
  return new Promise(resolve => {
    const src = spawn('tar', [...tarArgs, '-czf', '-', '.'], { stdio: ['ignore', 'pipe', 'ignore'] });
    // gzip reads the .part from stdin (it refuses a file name ending .part) and answers 2 for a warning only (macOS tar
    // pads its output with zeros); a copy cut short answers 1 and is removed, never moved.
    const dst = spawnOn(target, { command: `umask 077 && mkdir -p ${dir} && cat > ${part} && { gzip -t < ${part}; g=$?; [ $g = 0 ] || [ $g = 2 ]; } && mv ${part} ${dir}/${name}; s=$?; rm -f ${part}; [ $s = 0 ] && ls -1t ${dir}/${kind}-*.tgz | tail -n +15 | xargs -r rm -f; exit $s` });
    let tarCode = null, farCode = null, done = false;
    const timer = setTimeout(() => { src.kill('SIGKILL'); dst.kill('SIGKILL'); }, 180000);
    const finish = () => {
      if (done || tarCode === null || farCode === null) return;
      done = true;
      clearTimeout(timer);
      // GNU tar answers 1 when a file changed while it read it (a chat being saved): the copy is still good.
      resolve(farCode === 0 && tarCode <= 1);
    };
    src.on('close', c => { tarCode ??= c ?? 2; finish(); });
    src.on('error', () => { tarCode ??= 2; finish(); });
    // (the far side ending first leaves tar nobody to write to: it is stopped, and the copy doesn't count)
    dst.on('close', c => { farCode ??= c ?? 1; src.kill('SIGKILL'); finish(); });
    dst.on('error', () => { farCode ??= 1; src.kill('SIGKILL'); finish(); });
    src.stdout.pipe(dst.stdin);
    dst.stdin.on('error', () => {});
  });
}
async function backupState() {
  if (!BACKUP_ON || backingUp) return;
  backingUp = true;
  try {
    const day = dayOf(Date.now()), file = `state-${day}.tgz`, source = SOURCE_DIR && existsSync(SOURCE_DIR) ? `source-${day}.tgz` : null;
    const targets = backupTargets(), before = lastBackup;
    let to = null;
    for (const t of targets) {
      if (await sendCopy(t, ['-C', STATE_DIR, /* the excludes as found */], file)
        && (!source || await sendCopy(t, ['-C', SOURCE_DIR, '--exclude=node_modules'], source))) { to = t; break; }
    }
    const at = new Date().toISOString();
    const next = to ? { at, ok: true, to: to.id, file, source, good: { at, to: to.id, file, source }, noticedOn: before?.noticedOn || null }
      : { at, ok: false, error: targets.length ? `${targets.map(n => sparkName(n)).join(' and ')} didn’t take it` : 'there is no other Spark to copy to', good: before?.good || null, noticedOn: before?.noticedOn || null };
    // After a whole day without a copy: one notice a day.
    const g = next.good;
    if (!to && next.noticedOn !== day && !(g && String(g.at).slice(0, 10) >= dayOf(Date.now() - 86400000))) {
      next.noticedOn = day;
      fleetEvent({ type: 'notice', text: `Spark Console’s state ${g ? `was last copied to another Spark on ${String(g.at).slice(0, 10)} (${sparkName(nodeById(g.to) || { id: g.to })} holds it)` : 'has never been copied to another Spark'}. Today ${next.error}. It tries again every hour, and as soon as a Spark comes back.` });
    }
    lastBackup = next;
    try { writePrivate(BACKUP_FILE, next); } catch (e) { console.error(`Couldn’t save the daily copy’s record: ${e.message}`); }
  } finally { backingUp = false; }
}
// Ten minutes after a start, every hour, and from noteSparkStates when a Spark comes back.
function backupIfDue() {
  if (!BACKUP_ON || String(lastBackup?.good?.at).slice(0, 10) === dayOf(Date.now())) return;
  backupState().catch(e => console.error(`The daily copy: ${e.message}`));
}
if (BACKUP_ON) setTimeout(() => { backupIfDue(); setInterval(backupIfDue, Number(process.env.SPARK_CONSOLE_BACKUP_MS || 3600000)); }, Number(process.env.SPARK_CONSOLE_BACKUP_FIRST_MS || 600000));
```
`backupIfDue` must stay a `function` declaration (part 19 calls it). `lastBackup` stays null until a try runs or a record is on disk (fleet.test.mjs asserts null). SPARK_CONSOLE_BACKUP_MS now means "how often it checks" (default one hour). 24-handler.mjs needs no edit: /health already sends `lastBackup`, which now carries `good`, `source`, `noticedOn`.

