    // Synced to disk before it takes the file's place: after a power cut the file is the old one or the new one, never empty.
    const fd = openSync(tmp, 'w', 0o600);
    try { writeFileSync(fd, JSON.stringify(value, null, 2)); fsyncSync(fd); } finally { closeSync(fd); }
