    if (keptFiles.has(file)) { try { copyFileSync(file, `${file}.prev`); chmodSync(`${file}.prev`, 0o600); } catch {} }
    renameSync(tmp, file);
  } catch (e) {
    try { unlinkSync(tmp); } catch {}
    throw e;
  }
}

