function loadMainSetup() {
  const presets = mainPresets(), file = readJson(MAIN_FILE), saved = file?.current, r = file?.running;
  const ran = saved && r && r.id === saved && typeof r.model === 'string' && Array.isArray(r.args) ? { ...MAIN_DEFAULTS, ...r } : null;
  if (saved && presets[saved]) {
    const m = mainSetup(saved, presets[saved]);
    if (!ran) { try { writeMainFile({ ...file, running: m }); } catch (e) { console.error(`Couldn’t save Sparkie’s running setup: ${e.message}`); } }
    else if (startsDifferently(ran, m)) mainNotice(`This build of Spark Console starts Sparkie’s setup “${String(m.title || m.id).slice(0, 80)}” differently than its model was started. Its model keeps running as it is. The new settings apply when you stop and start Sparkie’s model. Nothing was restarted.`);
    return m;
  }
  if (ran) {
    mainNotice(`This build of Spark Console doesn’t list Sparkie’s setup “${String(ran.title || ran.id).slice(0, 80)}”. Sparkie keeps using it, the way its model was started. Nothing was restarted.`);
    return ran;
  }
  const id = Object.keys(presets)[0];
  return id ? mainSetup(id, presets[id]) : null;
}

