// … buildOf gives the same fingerprint for any folder holding a copy of the service (an install snapshot's).
const buildOf = dir => {
  const h = createHash('sha256');
  for (const f of ['server.mjs', 'dig.mjs', 'passkey.mjs']) h.update(readFileSync(`${String(dir).replace(/\/$/, '')}/${f}`));
