// The change log (docs/changes.md): one entry per install, written by the installer on Spark 2, and one "Undone" line
// when a build is taken out again. These run the installer's own bash (cut out of deploy/host-on-portal.sh) on
// temporary folders: no fleet, no Spark, nothing outside the temporary folder.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync, mkdirSync, mkdtempSync, rmSync, existsSync, cpSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { REPO } from './start-mock.mjs';

const installer = readFileSync(join(REPO, 'deploy', 'host-on-portal.sh'), 'utf8');
// A bash function as the installer has it: from "name() {" at the start of a line to the first "}" at the start of one.
const fn = name => installer.match(new RegExp(`^${name}\\(\\) \\{\\n[\\s\\S]*?\\n\\}\\n`, 'm'))?.[0];
const put = (file, text, mode) => { mkdirSync(dirname(file), { recursive: true }); writeFileSync(file, text, mode ? { mode } : undefined); };
const read = file => readFileSync(file, 'utf8');
const scratch = t => { const d = mkdtempSync(join(tmpdir(), 'sct-changes-')); t.after(() => rmSync(d, { recursive: true, force: true })); return d; };
// Only what is named reaches the script: no real HOME, and no way to reach the real systemd.
const bash = (script, env) => spawnSync('bash', ['-c', `set -euo pipefail\n${script}`], { encoding: 'utf8', env: { PATH: '/usr/bin:/bin', ...env } });
const HEAD = '# Change log\n\nOne entry for every install.\n';
const EARLIER = '\n## 2026-11-10, build 000000000001\n- What and why: the one before.\n- Result: installed and answering.\n';
const ENTRY = '## 2026-11-12, build 1a2b3c4d5e6f\n- What and why: A fix.\n- Gate: the whole suite passed for this build on 2026-11-12T01:42:56.625Z.\n';

test('the installer starts each entry with the build, the note as one line, and when the whole suite passed', t => {
  const code = fn('change_entry');
  assert.ok(code, 'deploy/host-on-portal.sh has change_entry()');
  const d = scratch(t);
  put(join(d, 'service', 'workflows.lock.json'), JSON.stringify({ build: '1a2b3c4d5e6f', testedAt: '2026-11-12T01:42:56.625Z' }));
  const env = { HERE: d, STAMP: '20261112T034500Z', API_BUILD: '1a2b3c4d5e6f', PATH: process.env.PATH };
  const r = bash(`${code}change_entry`, { ...env, NOTE: 'The restart word now starts a stopped brain.\nIt used to refuse.\n## not a heading' });
  assert.equal(r.status, 0, r.stderr);
  assert.equal(r.stdout, '## 2026-11-12, build 1a2b3c4d5e6f\n- What and why: The restart word now starts a stopped brain. It used to refuse. ## not a heading\n- Gate: the whole suite passed for this build on 2026-11-12T01:42:56.625Z.\n');
  const none = bash(`${code}change_entry`, env);
  assert.equal(none.status, 0, none.stderr);
  assert.equal(none.stdout.split('\n')[1], '- What and why: not given (say it when installing: NOTE="what changed and why")');
  assert.ok(installer.includes('install.sh source.tar change.md'), 'the entry goes to Spark 2 with the new files');
});

test('an install adds one entry to the log on Spark 2 and keeps the entries already there', t => {
  const code = fn('log_change');
  assert.ok(code, 'install.sh (in deploy/host-on-portal.sh) has log_change()');
  const d = scratch(t), old = join(d, 'src'), fresh = join(d, 'src.new'), IN = join(d, 'in');
  put(join(IN, 'change.md'), ENTRY);
  put(join(old, 'docs', 'changes.md'), HEAD + EARLIER);
  put(join(old, 'service', 'x.mjs'), 'one\n');
  put(join(old, 'service', 'same.mjs'), 'same\n');
  put(join(old, 'test', 'a.test.mjs'), "test('one', () => {});\n");
  put(join(fresh, 'docs', 'changes.md'), HEAD);                        // what a new source brings: no entries
  put(join(fresh, 'service', 'x.mjs'), 'two\n');
  put(join(fresh, 'service', 'same.mjs'), 'same\n');
  put(join(fresh, 'test', 'a.test.mjs'), "test('one', () => {});\n  test('two', () => {});\n");
  put(join(fresh, 'test', 'b.test.mjs'), "it('three', () => {});\n");
  const env = { IN, SNAP: join(d, 'releases', '20261112T034500Z') };
  const SAVED = ' The build before it is saved as 20261112T034500Z.\n';

  const r = bash(`${code}log_change "${fresh}" 'installed and answering.' "${old}"`, env);
  assert.equal(r.status, 0, r.stderr);
  assert.equal(read(join(fresh, 'docs', 'changes.md')), `${HEAD}${EARLIER}\n${ENTRY}`
    + '- Files changed: 3\n  - service/x.mjs\n  - test/a.test.mjs\n  - test/b.test.mjs\n'
    + '- Test blocks in the suite: 3 (the build before had 1)\n'
    + `- Result: installed and answering.${SAVED}`);
  assert.equal(read(join(old, 'docs', 'changes.md')), HEAD + EARLIER, 'the source before it is left as it was');

  // The same source again, and no snapshot: nothing changed, and nothing is said about a saved build.
  const twin = join(d, 'src.twin');
  cpSync(fresh, twin, { recursive: true });
  const same = bash(`${code}log_change "${fresh}" 'installed and answering.' "${twin}"`, { IN });
  assert.equal(same.status, 0, same.stderr);
  assert.ok(read(join(fresh, 'docs', 'changes.md')).endsWith(`\n${ENTRY}- Files changed: 0\n- Test blocks in the suite: 3 (the build before had 3)\n- Result: installed and answering.\n`));

  // More than 40 files: 40 are named, the rest counted.
  for (let i = 10; i < 52; i++) put(join(fresh, 'public', `f${i}.js`), `${i}\n`);
  const many = bash(`${code}log_change "${fresh}" 'installed and answering.' "${old}"`, env);
  assert.equal(many.status, 0, many.stderr);
  const last = read(join(fresh, 'docs', 'changes.md')).split(`\n${ENTRY}`).pop();
  assert.match(last, /^- Files changed: 45\n(  - \S+\n){40}  - and 5 more\n- Test blocks/);

  // A build that did not start: the entry goes in the source that stays, with no list of files.
  const failed = bash(`${code}log_change "${old}" 'it did not start.'`, env);
  assert.equal(failed.status, 0, failed.stderr);
  assert.equal(read(join(old, 'docs', 'changes.md')), `${HEAD}${EARLIER}\n${ENTRY}- Result: it did not start.${SAVED}`);

  // No entry came with the files: nothing is added, and the log already there is still carried over.
  rmSync(join(IN, 'change.md')); writeFileSync(join(fresh, 'docs', 'changes.md'), HEAD);
  const bare = bash(`${code}log_change "${fresh}" 'installed and answering.' "${old}"`, env);
  assert.equal(bare.status, 0, bare.stderr);
  assert.equal(read(join(fresh, 'docs', 'changes.md')), read(join(old, 'docs', 'changes.md')));

  // A source with no docs folder (or none at all) is left alone.
  const nowhere = bash(`${code}log_change "${join(d, 'missing')}" 'it did not start.'`, env);
  assert.equal(nowhere.status, 0, nowhere.stderr);
  assert.ok(!existsSync(join(d, 'missing')));

  // A log that can't be carried over fails, so the installer keeps the old source and its log.
  rmSync(join(fresh, 'docs'), { recursive: true });
  const lost = bash(`${code}log_change "${fresh}" 'installed and answering.' "${old}"`, env);
  assert.notEqual(lost.status, 0);
});

test('going back a build adds one Undone line, and works the same where there is no log', t => {
  const restore = installer.match(/<<'RESTORE'\n([\s\S]*?)\nRESTORE\n/)?.[1];
  assert.ok(restore, 'the installer writes restore.sh');
  const home = scratch(t), snap = join(home, 'releases', '20261112T034500Z'), bin = join(home, 'bin'), log = join(home, 'spark-console-src', 'docs', 'changes.md');
  put(join(snap, 'restore.sh'), `${restore}\n`);
  put(join(snap, 'spark-console-service', 'server.mjs'), 'the build before\n');
  put(join(home, 'spark-console-service', 'server.mjs'), 'the new build\n');
  // Stand-ins, first on a PATH with nothing else of ours; with no session variables, the real systemctl --user could not act anyway.
  put(join(bin, 'systemctl'), `#!/bin/sh\necho "$*" >> "${join(home, 'systemctl-calls')}"\n`, 0o755);
  put(join(bin, 'curl'), '#!/bin/sh\necho \'{"ok":true}\'\n', 0o755);
  const env = { HOME: home, PATH: `${bin}:/usr/bin:/bin` };
  assert.equal(bash('command -v systemctl', env).stdout.trim(), join(bin, 'systemctl'));
  put(log, HEAD + EARLIER);
  const r = spawnSync('bash', [join(snap, 'restore.sh')], { encoding: 'utf8', env });
  assert.equal(r.status, 0, r.stderr);
  assert.equal(read(join(home, 'spark-console-service', 'server.mjs')), 'the build before\n');
  assert.match(read(join(home, 'systemctl-calls')), /^--user restart spark-console-api$/m);
  const text = read(log);
  assert.ok(text.startsWith(HEAD + EARLIER), 'what was in the log stays');
  assert.match(text.slice((HEAD + EARLIER).length), /^- Undone \d{4}-\d{2}-\d{2}: the build saved as 20261112T034500Z was put back\.\n$/);
  rmSync(join(home, 'spark-console-src'), { recursive: true });
  const again = spawnSync('bash', [join(snap, 'restore.sh')], { encoding: 'utf8', env });
  assert.equal(again.status, 0, again.stderr);
  assert.ok(!existsSync(join(home, 'spark-console-src')), 'no log is made where there was none');
});

