New file /Users/akuppala/Documents/26aiRAG/spark-console/test/heal-unwatched.test.mjs (picked up by lock.mjs's glob). Proven on a scratch copy: fails on today's code, passes with the change, fails again without `|| e.inferred`.

How it sets up the stand-in fleet (its own `useFleet`, all in `prepare`, before the service starts, as a console restart after a power cut would find things): Spark 4's `sc-RadixArk--Qwen3.8-27B-NVFP4` is rewritten to `exited|Exited (255) 5 minutes ago`; `~/.mock/status.json` gives Spark 4 `uptimeSeconds: 60` and Spark 3 `500000`; `knowledge.json` says both are online, last seen 10 minutes ago, Spark 4's boot three days ago, Spark 3's boot exactly its uptime ago; `desired.json` lists the Spark 4 model. `SPARK_CONSOLE_HEAL_OFFLINE_MS` is one hour, so only the `inferred` rule can count the pair.

What it asserts: one `spark-online` for spark4 with `inferred: true` and `upSeconds: 60`; one `spark-offline` with `inferred: true`, `last: null`, stamped no earlier than the last-seen time and no later than 59 s before the online one; the new `bootAt` saved in knowledge.json; a `healing` event "Spark 4 came back on"; Self-healing's `restart` operation completed and the container running; exactly one inferred pair for spark4 and none for spark3.

Full text:

// A power cycle Spark Console didn't watch (S7, 2026-11-11). The console was down itself while a Spark lost power and
// came back (a power cut that took every Spark, Spark 2 restarting), so no "went offline" or "came back" was written
// and nothing on the list of what should be running came back. Now the Spark's own uptime says it booted after the boot
// on record: the two missed events are written (inferred: true), once per boot, and self-healing brings the model back
// as after any power-on.
// The fleet starts as that restart would find it: Spark 4's model exited 255 and is on the list, Spark 4 has been up
// 60 s, and the record says "online" with a boot three days ago. Spark 3's record matches its boot: nothing is written
// for it. (The floor for "dark long enough" is an hour here: a pair worked out from the boot time counts whatever the gap.)
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { T, useFleet, eventLines, waitFor, SLOW } from './lib.mjs';

const MODEL = 'RadixArk--Qwen3.8-27B-NVFP4', RADIX = `sc-${MODEL}`, UP3 = 500000;
const SEEN = new Date(Date.now() - 10 * 60000).toISOString();
useFleet({ watchMs: 2000, statusMs: 3000,
  env: { SPARK_CONSOLE_HEAL_MS: '2000', SPARK_CONSOLE_HEAL_SETTLE_MS: '3000', SPARK_CONSOLE_HEAL_OFFLINE_MS: '3600000' },
  prepare: ({ root, stateDir }) => {
    const mock = (spark, file) => join(root, spark, '.mock', file);
    const before = readFileSync(mock('spark4', 'containers'), 'utf8');
    const after = before.replace(new RegExp(`^${RADIX.replace(/[.+]/g, '\\$&')}\\|running\\|[^|]*\\|`, 'm'), `${RADIX}|exited|Exited (255) 5 minutes ago|`);
    assert.notEqual(after, before, `${RADIX} wasn't running on the stand-in Spark 4`);
    writeFileSync(mock('spark4', 'containers'), after);
    rmSync(mock('spark4', `up-${RADIX}`), { force: true });
    writeFileSync(mock('spark4', 'status.json'), JSON.stringify({ uptimeSeconds: 60 }));
    writeFileSync(mock('spark3', 'status.json'), JSON.stringify({ uptimeSeconds: UP3 }));
    writeFileSync(join(stateDir, 'knowledge.json'), JSON.stringify({ workloads: {}, sparks: {
      spark4: { online: true, lastSeenAt: SEEN, bootAt: new Date(Date.now() - 3 * 86400000).toISOString() },
      spark3: { online: true, lastSeenAt: SEEN, bootAt: new Date(Date.now() - UP3 * 1000).toISOString() } } }), { mode: 0o600 });
    writeFileSync(join(stateDir, 'desired.json'), JSON.stringify({ revision: 1, revisions: [],
      running: [{ spark: 'spark4', container: RADIX, model: MODEL, since: SEEN, by: 'owner@test' }] }), { mode: 0o600 });
  },
});

const stateOf = (spark, name) => readFileSync(join(T.fleet.root, spark, '.mock', 'containers'), 'utf8').split('\n').find(l => l.startsWith(`${name}|`))?.split('|')[1];
const inferred = (type, spark) => eventLines().filter(e => e.type === type && e.spark === spark && e.inferred === true);

test('a Spark that restarted while Spark Console was down: the missed offline and online are written once, and its model comes back', { timeout: 420000 * SLOW }, async () => {
  const on = await waitFor(() => inferred('spark-online', 'spark4')[0], { timeout: 90000, what: 'the missed "came back" being written' });
  assert.equal(on.upSeconds, 60);
  const off = inferred('spark-offline', 'spark4')[0];
  assert.ok(off, 'the missed "went offline" is written with it');
  assert.equal(off.last, null, 'no reading is made up');
  // Stamped with when Spark 4 was last seen, never later than its boot (60 s before it was found up).
  assert.ok(Date.parse(off.at) >= Date.parse(SEEN) && Date.parse(off.at) <= Date.parse(on.at) - 59000, `offline stamped ${off.at}, online ${on.at}`);
  // The new boot time is saved at once, so the next restart of Spark Console doesn't write the pair again.
  const bootSaved = () => Date.parse(JSON.parse(readFileSync(join(T.fleet.stateDir, 'knowledge.json'), 'utf8')).sparks?.spark4?.bootAt);
