// After a restart: a chat whose last message is a question nobody answered (the restart cut the turn) gets one notice.
// Nothing is run again. Only questions under 30 minutes old, and never Spark Console's own carry-on message.
function chatsAfterRestart() {
  const now = Date.now();
  let told = 0;
  for (const conv of chatData().conversations) {
    const last = conv.messages.at(-1);
    if (!last || last.role !== 'user' || last.auto || now - Date.parse(last.createdAt) > 30 * 60000) continue;
    const at = new Date().toISOString();
    conv.messages.push({ role: 'assistant', content: `Spark Console restarted before ${ASSISTANT_NAME} answered that. If you asked for a change, check whether it happened before you send it again.`, createdAt: at, notice: true, status: 'interrupted' });
    conv.updatedAt = at;
    told++;
  }
  if (told) saveChats();
}
```
