// Saves that failed, by file name; a later save of the same file that works clears it (20-needs.mjs reads it).
const saveFailed = new Map();
const noteSave = (file, e) => { const name = String(file).split('/').pop(); if (e) saveFailed.set(name, { at: new Date().toISOString(), code: e.code || 'error' }); else saveFailed.delete(name); };
function writePrivate(file, value) {
  try {
    mkdirSync(STATE_DIR, { recursive: true, mode: 0o700 });
    const tmp = `${file}.${process.pid}.tmp`;
    writeFileSync(tmp, JSON.stringify(value, null, 2), { mode: 0o600 });
    renameSync(tmp, file);
    noteSave(file);
  } catch (e) { noteSave(file, e); throw e; }
