/* ───────── what is waiting on the owner (H4) ───────── */
// One list of open problems, built by code each time it is asked for, from facts Spark Console already holds: no model
// call, no look at another Spark, and no text from a log, an error, a container's output or the web (fleet_status
// carries it and stays a read of the console's own numbers). At most 8 lines, lock-out and data loss first. A line
// stands while its cause does and goes when the cause goes, never because it was shown. Said in /status (page and
// Telegram), at the top of Sparkie's fleet notes and as needsOwner in fleet_status. Nothing is pushed anywhere.
const NEEDS_MAX = 8, DAY_MS = 86400000;
const SAVE_WHY = { ENOSPC: 'the disk is full', EDQUOT: 'the disk is full', EACCES: 'the folder can’t be written', EPERM: 'the folder can’t be written', EROFS: 'the folder can’t be written' };
const tilde = p => String(p).replace(homedir(), '~');

// Whether Spark Console starts with its Spark after a power cut (the owner turns linger on once, with sudo). Read only:
// true, false, or null when it can't be told. Looked at shortly after start, then every hour.
let lingerOn = null;
async function readLinger() {
  try {
    const node = NODES.find(n => n.host === 'local');
    if (!node) return;
    const r = await run(node, `printf 'linger\\t%s\\n' "$(loginctl show-user "$(id -un)" -p Linger --value 2>/dev/null)"`, { timeout: 15000 });
    if (r.code !== 0) return;
    const v = fields(r.out, 'linger')[0]?.[0];
    lingerOn = v === 'yes' ? true : v === 'no' ? false : null;
  } catch {}
}
setTimeout(() => { readLinger(); setInterval(readLinger, Number(process.env.SPARK_CONSOLE_LINGER_MS || 3600000)).unref(); }, 5000).unref();

function openProblems() {
  const out = [], add = (id, text) => out.push({ id, text });
  const hereNode = NODES.find(n => n.host === 'local'), here = hereNode ? sparkName(hereNode) : 'the Spark that runs Spark Console';
  const sources = [
    () => {
      if (!saveFailed.size) return;
      const names = [...saveFailed.keys()], last = [...saveFailed.values()].at(-1);
      add('saves', `Spark Console couldn’t save ${names.slice(0, 4).join(', ')}${names.length > 4 ? ` and ${names.length - 4} more` : ''} (${SAVE_WHY[last.code] || 'the write failed'}). What changed since is only in memory and is lost at a restart. Free space or fix the folder ${tilde(STATE_DIR)} on ${here}.`);
    },
    () => { if (SECRETS_FILE && secretsRead() === null) add('secrets', `The secrets file on ${here} can’t be read, so Telegram and recovery codes are off. Fix or remove ${tilde(SECRETS_FILE)} there; Spark Console never writes over it.`); },
    () => {
      const exp = Date.parse(tsKeyExpiry || '');
      if (!Number.isFinite(exp)) return;
      const days = Math.floor((exp - Date.now()) / DAY_MS);
      if (days < 14) add('key', `${here}’s Tailscale key ${days < 0 ? 'has expired' : days === 0 ? 'expires today' : `expires in ${days} day${days === 1 ? '' : 's'}`} (${new Date(exp).toISOString().slice(0, 10)}). Once it has, the page, the internet address and the other Sparks can’t reach ${here}. In Tailscale’s admin page, under Machines, turn off key expiry for ${here}.`);
    },
    () => { if (lingerOn === false) add('linger', `After a power cut or a restart of ${here}, Spark Console won’t start until someone logs in there. Run once on ${here}: sudo loginctl enable-linger $USER`); },
    () => {
      const free = gbOfGiB(statusCache?.value.nodes.find(n => n.id === hereNode?.id)?.diskFreeGiB);
      if (free !== null && free < 10) add('disk', `${here} has ${free} GB of disk left (under 10). When it fills, chats and settings stop saving. Free some space there.`);
    },
    () => {
      const held = (heldLast || []).filter(x => !x.sparkOff);
      if (held.length) add('held', `Should be running but ${held.length === 1 ? 'isn’t' : 'aren’t'}: ${held.slice(0, 3).map(x => `${String(x.container).slice(0, 80)} on ${sparkName(nodeById(x.spark) || { id: x.spark })}`).join(', ')}${held.length > 3 ? ` and ${held.length - 3} more` : ''}. Say “bring back” and the name to start one again; “what should be running?” says why.`);
    },
    () => {
      if (!BACKUP_ON) return;
      const since = lastGoodBackupAt || STARTED_AT;
      if (Date.now() - Date.parse(since) > 2 * DAY_MS) add('copy', `Spark Console’s state hasn’t been copied to another Spark since ${since.slice(0, 10)}${lastGoodBackupAt ? '' : ' (when Spark Console last started)'}. It tries once a day and needs another Spark on at that time. Until then, losing ${here}’s disk would lose what changed since.`);
    },
    () => { if (funnelWasOn && funnelOn === false) add('funnel', 'Spark Console was open to the internet and isn’t now, so devices without Tailscale can’t reach it. Tailscale on your devices still works. To open it again, run deploy/open-to-internet.sh.'); },
    () => {
      const names = [...new Set(readdirSync(STATE_DIR).map(f => /^([a-z0-9-]+\.jsonl?)\.unreadable-[\w-]+$/i.exec(f)?.[1]).filter(Boolean))];
      if (names.length) add('aside', `Spark Console set aside ${names.length === 1 ? 'a file' : `${names.length} files`} it couldn’t read (${names.slice(0, 4).join(', ')}) and started ${names.length === 1 ? 'it' : 'them'} empty. What ${names.length === 1 ? 'it' : 'they'} held is kept in ${tilde(STATE_DIR)} on ${here}, with “.unreadable-” in the name. Look there; moving the kept file out of that folder clears this line.`);
    },
    () => {
      const at = readFileSync(`${STATE_DIR}/watchdog-restarts`, 'utf8').split('\n').map(Number).filter(t => t > 0 && Date.now() - t * 1000 < DAY_MS);
