```js
/* the needs-me line (R32; the owner's decision 6, 2026-11-11) */
// Switched on by the owner in Spark Console with the passkey. When something new joins the open-problems list, one fixed
// line goes to the paired chat: a count and where to look, nothing from the list. At most 3 in 24 hours. A problem
// already told counts as new again only after 6 hours off the list. No brain turn, no action.
const NEEDS_MS = Number(process.env.SPARK_CONSOLE_NEEDS_MS || 60000), NEEDS_A_DAY = 3, NEEDS_AGAIN_MS = 6 * 3600000;
const needsLine = n => `Spark Console: ${n === 1 ? '1 thing needs' : `${n} things need`} you. Send /status to see ${n === 1 ? 'it' : 'them'}.`;
// Told problems that are off the list: when this process first saw each gone (memory only, so a restart never re-tells).
const needsGone = new Map();
let needsBusy = false;
async function needsMeTick() {
  if (needsBusy || draining) return;
  needsBusy = true;
  try {
    if (tgPaired()?.needsMe !== true || tg.state !== 'ok') return;
    const open = [...new Set((await openProblems()).map(p => String(p.key)))], now = Date.now();
    const st = tgSaved(), n = st.needs || {};
    const told = (n.told || []).filter(k => {
      if (open.includes(k)) { needsGone.delete(k); return true; }
      if (!needsGone.has(k)) needsGone.set(k, now);
      return now - needsGone.get(k) < NEEDS_AGAIN_MS;
    });
    const sent = (n.sent || []).filter(t => now - t < 86400000);
    if (!open.some(k => !told.includes(k)) || sent.length >= NEEDS_A_DAY) return;
    if (!await tell('needs', needsLine(open.length))) return;
    st.needs = { told: [...new Set([...told, ...open])], sent: [...sent, now] };
    tgSave();
  } catch (e) { console.error(`The needs-me line: ${e.message}`); } finally { needsBusy = false; }
}
