// A switch keeps the new model only if it can call a tool (H6): one question, asked the way Sparkie's turn asks (the
// same prompt, tools and request shape as `base` in sparkieTurn, 14-chats.mjs), answered within a minute. Only the reply
// is read: nothing it asks for is run. What it throws are fixed lines (they go on the fleet's record); the server's
// own words stay in the operation's log.
const TOOL_CHECK_MS = 60000;
async function toolCheck(job, m) {
  step(job, `Checking that ${m.title} can call a tool`);
  const started = Date.now();
  const body = { model: m.served, stream: true, max_tokens: m.maxTokens || 4096, ...(m.sampling || { temperature: 0.3, top_p: 0.8 }),
    chat_template_kwargs: { enable_thinking: Boolean(m.thinking), ...(m.templateKwargs || {}) },
    messages: [{ role: 'system', content: systemPrompt(null, true) }, { role: 'user', content: 'What is running?' }],
    tools: sparkieTools(), tool_choice: 'auto' };
  let text;
  modelInUse++;
  try {
    text = await Promise.race([httpJson('127.0.0.1', m.port, '/v1/chat/completions', body, { timeout: TOOL_CHECK_MS }),
      sleep(TOOL_CHECK_MS).then(() => { throw new Error('timed out'); })]);
  } catch (e) {
    if (e.message === 'timed out') throw new Error('The test question got no reply within a minute.');
    note(job, `Its server said: ${maskSecrets(e.message).slice(0, 300)}`);
    throw new Error('Its server turned the test question down.');
  } finally { modelInUse--; }
  const calls = [];
  for (const line of text.split('\n')) {
    if (!line.startsWith('data:')) continue;
    let ev;
    try { ev = JSON.parse(line.slice(5)); } catch { continue; }
    for (const tc of ev.choices?.[0]?.delta?.tool_calls || []) {
      const c = (calls[tc.index ?? 0] ||= { name: '', args: '' });
      if (tc.function?.name) c.name += tc.function.name;
      if (tc.function?.arguments) c.args += tc.function.arguments;
    }
  }
  const readable = c => { try { const a = JSON.parse(c.args || '{}'); return Boolean(a) && typeof a === 'object' && !Array.isArray(a); } catch { return false; } };
  if (!calls.some(Boolean)) throw new Error('It replied in words and called no tool.');
  if (!calls.some(c => c && ACTIONS.has(c.name) && readable(c))) throw new Error('It asked for a tool Spark Console doesn’t have, or with arguments that can’t be read.');
  note(job, `${m.title} called a tool in ${((Date.now() - started) / 1000).toFixed(1)} s`);
}
