```js
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync, existsSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { T, useFleet, api, waitFor, newChat, say, SLOW } from './lib.mjs';

useFleet({ watchMs: 60000, statusMs: 3000, knowledge: true, env: { SPARK_CONSOLE_DESIRED_MS: '1500' } });
const WORDS = 'Anything need me?', NAME = 'testorg--Qwen3.8-27B-abliterated-GGUF', TESTORG = `sc-${NAME}`;
const fleetStatus = async () => { const r = await api('/actions/fleet_status', { method: 'POST', body: {} }); assert.equal(r.status, 200, r.text); return r.json; };
const requests = () => (existsSync(join(T.fleet.dir, 'model-requests.jsonl')) ? readFileSync(join(T.fleet.dir, 'model-requests.jsonl'), 'utf8').trim().split('\n').map(l => JSON.parse(l)) : []);
async function ask() {
  const rules = join(T.fleet.dir, 'model-script.json');
  writeFileSync(rules, JSON.stringify([{ match: 'anything need me', calls: [{ name: 'fleet_status', arguments: {} }] }]));
  try {
    const chat = await newChat(), from = requests().length, r = await say(chat, WORDS);
    const mine = requests().slice(from).filter(x => x.words === WORDS);
    return { r, record: mine[0]?.lastUser || '', results: mine.filter(x => x.lastRole === 'tool').flatMap(x => x.results.map(y => y.content)) };
  } finally { rmSync(rules, { force: true }); }
}
function setState(spark, name, state, status) {
  const f = join(T.fleet.root, spark, '.mock', 'containers');
  writeFileSync(f, readFileSync(f, 'utf8').split('\n').map(l => (l.startsWith(`${name}|`) ? l.split('|').map((v, i) => (i === 1 ? state : i === 2 ? status : v)).join('|') : l)).join('\n'));
}

test('nothing waiting: needsOwner is an empty list right after observedAt, and that is what Sparkie is told', { timeout: 60000 * SLOW }, async () => {
  const s = await fleetStatus();
  assert.deepEqual(Object.keys(s).slice(0, 2), ['observedAt', 'needsOwner']);
  assert.deepEqual(s.needsOwner, []);
  const { r, results } = await ask();
  assert.deepEqual(r.tools.map(t => [t.name, t.ok, t.change]), [['fleet_status', true, false]]);
  assert.match(results[0], /^\{"observedAt":"[^"]+","needsOwner":\[\],"sparks":\[/);
  assert.match(r.text, /fleet_status said: \{"observedAt":"[^"]+","needsOwner":\[\]/);
});

test('a model that should run but was stopped outside Spark Console: one line naming it and its Spark, the same line as in Sparkie’s record; asking doesn’t clear it, forgetting the model does', { timeout: 180000 * SLOW }, async () => {
  await waitFor(async () => (await api('/desired')).json.running?.some(e => e.spark === 'spark3' && e.container === TESTORG && e.state === 'running'), { timeout: 60000, what: 'the should-run list' });
  setState('spark3', TESTORG, 'exited', 'Exited (0) just now');
  try {
    const lines = await waitFor(async () => { const n = (await fleetStatus()).needsOwner; return n.length ? n : null; }, { timeout: 60000, what: 'a line in needsOwner' });
    assert.ok(lines.length <= 8 && lines.every(l => typeof l === 'string' && l.trim()), JSON.stringify(lines));
    const line = lines.find(l => l.includes(NAME) && l.includes('Spark 3'));
    assert.ok(line, JSON.stringify(lines));
    const { r, record, results } = await ask();
    assert.deepEqual(r.tools.map(t => t.name), ['fleet_status']);
