```js
// What a running container was really started with, read from Docker now (one docker inspect): its image, its engine
// (by the command Spark Console starts each engine with) and its flags. null when Docker gave nothing to read.
async function ranWith(node, container) {
  const r = await run(node, `docker inspect ${q(container)} 2>/dev/null | head -c 300000 | base64 | tr -d '\\n'`, { timeout: 20000 });
  const cfg = b64json(r.out.trim())?.[0]?.Config;
  if (!cfg) return null;
  const cmd = [...(cfg.Entrypoint || []), ...(cfg.Cmd || [])].map(String), from = cmd.findIndex(a => a.startsWith('-'));
  return { image: String(cfg.Image || ''), flags: from < 0 ? [] : cmd.slice(from),
    engine: Object.keys(ENGINES).find(k => ENGINES[k].entry === cmd[0] && ENGINES[k].head.every((h, i) => cmd[i + 1] === h)) || null };
}
```

STEP 2. In adoptRunning's inner loop, keep the "really answers" check as it is. Replace the `await recordVerified(job, { model, engine: engineOf(model), image: imageOf(model), args: (model.manifest?.args || []).map(String), ...` call with:

```js
        // And only one that runs exactly as the model's own settings say is saved under them. One started from a Recipes
        // setup, a past run or a fix runs with other settings: its own start recorded those, and they aren't guessed here.
        const engine = engineOf(model), image = imageOf(model), args = (model.manifest?.args || []).map(String);
        const ran = await ranWith(nodeById(sp.id), d.container);
        if (!ran || ran.engine !== engine || ran.image !== image || !sameFlags(ran.flags, [...ENGINES[engine].tail('x'), ...args])) continue;
        await recordVerified(job, { model, engine, image, args,
          env: d.cluster ? model.manifest?.cluster?.env || {} : {}, nodes: d.cluster ? d.cluster.split('+') : [sp.id],
          host: local && !d.cluster ? '127.0.0.1' : sp.tsip, port: CONFIG.servePort, onlyIfNew: true });
```

